export const generateQRCodeDataURL = (text) => {
  const canvas = document.createElement('canvas');
  canvas.width = 200;
  canvas.height = 200;
  const ctx = canvas.getContext('2d');
  
  // Fondo blanco
  ctx.fillStyle = 'white';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  
  // Código QR simulado (texto centrado)
  ctx.fillStyle = 'black';
  ctx.font = 'bold 16px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('QR Code', canvas.width / 2, canvas.height / 2 - 10);
  
  ctx.font = 'bold 12px Arial';
  ctx.fillText(text, canvas.width / 2, canvas.height / 2 + 15);
  
  // Borde
  ctx.strokeStyle = '#4f46e5';
  ctx.lineWidth = 2;
  ctx.strokeRect(5, 5, canvas.width - 10, canvas.height - 10);
  
  return canvas.toDataURL('image/png');
};

export const generateCredentialImage = (employee) => {
  const canvas = document.createElement('canvas');
  canvas.width = 400;
  canvas.height = 250;
  const ctx = canvas.getContext('2d');
  
  // Gradiente de fondo
  const gradient = ctx.createLinearGradient(0, 0, 0, canvas.height);
  gradient.addColorStop(0, '#4f46e5');
  gradient.addColorStop(1, '#7c3aed');
  
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  
  // Área de contenido blanca
  ctx.fillStyle = 'white';
  ctx.fillRect(20, 20, canvas.width - 40, canvas.height - 40);
  
  // Encabezado de la empresa
  ctx.fillStyle = '#4f46e5';
  ctx.fillRect(20, 20, canvas.width - 40, 50);
  
  ctx.fillStyle = 'white';
  ctx.font = 'bold 18px Arial';
  ctx.textAlign = 'center';
  ctx.fillText('EMPRESA TECNOLOGÍA S.A.', canvas.width / 2, 50);
  
  // Información del empleado
  ctx.fillStyle = '#1f2937';
  ctx.font = 'bold 16px Arial';
  ctx.textAlign = 'left';
  ctx.fillText('CREDENCIAL DE EMPLEADO', 30, 90);
  
  ctx.font = '14px Arial';
  ctx.fillText(`Nombre: ${employee.name}`, 30, 120);
  ctx.fillText(`Puesto: ${employee.position}`, 30, 145);
  ctx.fillText(`Departamento: ${employee.department}`, 30, 170);
  ctx.fillText(`Código: ${employee.qrCode}`, 30, 195);
  
  // Área del código QR
  ctx.fillStyle = '#f3f4f6';
  ctx.fillRect(260, 100, 110, 110);
  ctx.fillStyle = '#4f46e5';
  ctx.font = 'bold 12px Arial';
  ctx.textAlign = 'center';
  ctx.fillText(employee.qrCode, 315, 155);
  
  return canvas.toDataURL('image/png');
};
